body.l-grid9 main {
  display: grid; grid-template-columns: repeat(3, 1fr); grid-auto-rows: minmax(180px, auto);
  gap: 16px; max-width: 1080px; margin: 0 auto; padding: 40px 24px 24px;
}
body.l-grid9 main section {
  padding: 24px; margin: 0; max-width: none;
  border: 1.5px solid var(--border); background: var(--surface);
}
body.l-grid9 #projects { grid-column: 1 / 3; grid-row: 1 / 3; }
body.l-grid9 #skills { grid-column: 3; grid-row: 1 / 2; }
body.l-grid9 #about { grid-column: 3; grid-row: 2 / 3; }
body.l-grid9 #blog { grid-column: 1; grid-row: 3; }
body.l-grid9 #contact { grid-column: 2 / 4; grid-row: 3; }
body.l-grid9 .section-desc, body.l-grid9 .skills-note { display: none; }
